INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beginnen alle IPv6-Adressen im Link-Local-Bereich mit FE80::/10?', 2, '[{"text": "Ja", "correct": true, "because": "FE80::/10 ist für Link-Local-Adressen reserviert"}, {"text": "Nein", "correct": false, "because": "Das ist der Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IPv6-Multicast-Adressen für die direkte Kommunikation mit einem einzelnen Gerät verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast ist für Gruppen, nicht Einzelgeräte"}, {"text": "Ja", "correct": false, "because": "Unicast ist dafür geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind IPv6-Adressen im Bereich 2000::/3 für globale Unicast-Adressen reserviert?', 2, '[{"text": "Ja", "correct": true, "because": "2000::/3 ist für routbare Unicast-Adressen"}, {"text": "Nein", "correct": false, "because": "Das ist der globale Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Geräte im selben Subnetz denselben IPv6-Adressbereich verwenden?', 2, '[{"text": "Ja", "correct": true, "because": "Subnetz definiert den Adressbereich"}, {"text": "Nein", "correct": false, "because": "Gemeinsamer Bereich ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Adressbereich FF00::/8 für IPv6-Multicast-Adressen reserviert?', 2, '[{"text": "Ja", "correct": true, "because": "FF00::/8 ist der Multicast-Bereich"}, {"text": "Nein", "correct": false, "because": "Das ist der Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher IPv6-Adressbereich wird für Link-Local-Adressen verwendet?', 2, '[{"text": "FE80::/10", "correct": true, "because": "Reserviert für lokale Verbindungen"}, {"text": "2000::/3", "correct": false, "because": "Globale Unicast-Adressen"}, {"text": "FF00::/8", "correct": false, "because": "Multicast-Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich kennzeichnet globale Unicast-Adressen?', 3, '[{"text": "2000::/3", "correct": true, "because": "Für weltweit routbare Adressen"}, {"text": "FC00::/7", "correct": false, "because": "Unique Local Adressen"}, {"text": "FEC0::/10", "correct": false, "because": "Veraltet, Site-Local"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich wird für IPv6-Multicast-Adressen verwendet?', 2, '[{"text": "FF00::/8", "correct": true, "because": "Multicast-Bereich"}, {"text": "FE80::/10", "correct": false, "because": "Link-Local"}, {"text": "2001::/32", "correct": false, "because": "Teredo-Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse gehört zum Unique Local Address (ULA)-Bereich?', 2, '[{"text": "FC00::1", "correct": true, "because": "FC00::/7 ist für ULA reserviert"}, {"text": "2001:db8::1", "correct": false, "because": "Globale Unicast"}, {"text": "FE80::1", "correct": false, "because": "Link-Local"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich wird für die Loopback-Adresse in IPv6 verwendet?', 2, '[{"text": "::1/128", "correct": true, "because": "Loopback ist ::1"}, {"text": "::/128", "correct": false, "because": "Unspecified Address"}, {"text": "FF01::1/128", "correct": false, "because": "Multicast"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche IPv6-Adressbereiche gibt es?', 4, '[{"text": "Link-Local (FE80::/10)", "correct": true, "because": "Für lokale Verbindungen"}, {"text": "Global Unicast (2000::/3)", "correct": true, "because": "Für Internet"}, {"text": "Multicast (FF00::/8)", "correct": true, "because": "Für Gruppenkommunikation"}, {"text": "Broadcast (255.255.255.255)", "correct": false, "because": "Gibt es in IPv6 nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen gehören zum Link-Local-Bereich?', 3, '[{"text": "FE80::1", "correct": true, "because": "Link-Local beginnt mit FE80"}, {"text": "FEC0::1", "correct": false, "because": "Veralteter Site-Local-Bereich"}, {"text": "FE80::abcd:1234", "correct": true, "because": "Im FE80::/10-Bereich"}, {"text": "2001:db8::1", "correct": false, "because": "Globale Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat der globale Unicast-Adressbereich?', 4, '[{"text": "Beginnt mit 2000::/3", "correct": true, "because": "Reserviert für globale Adressen"}, {"text": "Weltweit routbar", "correct": true, "because": "Für Internet geeignet"}, {"text": "Nur lokal gültig", "correct": false, "because": "Nicht lokal beschränkt"}, {"text": "Von ISPs zugewiesen", "correct": true, "because": "Provider vergeben Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressbereiche werden für spezielle Zwecke in IPv6 genutzt?', 3, '[{"text": "::/128 (Unspecified)", "correct": true, "because": "Keine Adresse angegeben"}, {"text": "::1/128 (Loopback)", "correct": true, "because": "Lokale Rückkopplung"}, {"text": "FC00::/7 (Unique Local)", "correct": true, "because": "Private Netzwerke"}, {"text": "192.168.0.0/16", "correct": false, "because": "IPv4-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen könnten in einem Multicast-Bereich vorkommen?', 3, '[{"text": "FF02::1", "correct": true, "because": "Link-Local Multicast"}, {"text": "FF05::2", "correct": true, "because": "Site-Local Multicast"}, {"text": "FF00::abcd", "correct": true, "because": "Im Multicast-Bereich"}, {"text": "FE80::2", "correct": false, "because": "Link-Local Unicast"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Link-Local-Adressen beginnen mit FE80::/10. b) Globale Unicast-Adressen sind nur lokal gültig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "FE80 ja, globale Adressen routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast-Adressen starten mit FF00::/8. b) Die Loopback-Adresse ist ::/128.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "FF00 ja, Loopback ist ::1/128"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unique Local Adressen (ULA) sind in FC00::/7. b) Link-Local-Adressen sind global routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ULA ja, Link-Local nicht routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) 2000::/3 ist für globale Unicast-Adressen reserviert. b) FF02::1 ist eine Multicast-Adresse.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "2000::/3 global, FF02::1 Multicast"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ::1 ist die IPv6-Loopback-Adresse. b) IPv6 verwendet Broadcast-Adressen wie IPv4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Loopback ja, Broadcast nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

